	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agents/{agentId}/webhooks/{path}/secret", wrapper.RotateWebhookSecret)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/runs/throughput", wrapper.GetThroughput)
